import unittest
from bounds import inclusive_sum

class IssueTests(unittest.TestCase):
    def test_includes_stop(self):
        self.assertEqual(inclusive_sum(2, 5), 14)

    def test_single_value(self):
        self.assertEqual(inclusive_sum(4, 4), 4)

    def test_negatives(self):
        self.assertEqual(inclusive_sum(-2, 2), 0)

